import{auth as e}from"./firebase.js";import{createUserWithEmailAndPassword as t,updateProfile as l}from"https://www.gstatic.com/firebasejs/10.12.2/firebase-auth.js";let signupBtn=document.getElementById("signupBtn");signupBtn&&signupBtn.addEventListener("click",async()=>{let s=document.getElementById("name").value.trim(),i=document.getElementById("email").value.trim(),n=document.getElementById("password").value.trim(),r=document.getElementById("message");if(!s||!i||!n){r.style.color="red",r.innerText="Please fill all fields";return}try{let a=await t(e,i,n);await l(a.user,{displayName:s}),r.style.color="green",r.innerText="Signup Successful",setTimeout(()=>{window.location.href="index.html"},1e3)}catch(m){console.log(m),r.style.color="red",r.innerText=m.message}});